'@

if (Test-Path -LiteralPath $Destination) {
    if (-not $Force) {
        throw "Destination already exists: $Destination. Re-run with -Force to replace it."
    }
    Remove-Item -LiteralPath $Destination -Recurse -Force
}

New-Item -ItemType Directory -Path $Destination -Force | Out-Null
$tempZip = Join-Path ([System.IO.Path]::GetTempPath()) ('cdt-workflow-' + [System.Guid]::NewGuid().ToString('N') + '.zip')
try {
    $bytes = [System.Convert]::FromBase64String(($archiveBase64 -replace '\s', ''))
    [System.IO.File]::WriteAllBytes($tempZip, $bytes)
    Expand-Archive -LiteralPath $tempZip -DestinationPath $Destination -Force
}
finally {
    if (Test-Path -LiteralPath $tempZip) {
        Remove-Item -LiteralPath $tempZip -Force
    }
}

Write-Host "Restored repository to $Destination"